{
  "title": "Rescue at the Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team arrives at the broken outer gate.",
      "visual_description": "A collapsed stone archway with rusted iron hinges, old royal banners hanging torn from the lintel. Mara the Cartographer unrolls a damp map while Tin Fox sniffs the rubble.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "Inside a dark market street, Oracle Lamp flickers blue. Its single eye stares at a spiral tower visible above rooflines. Mara holds the compass steady.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Sleeping Tax Collector blocks a passage.",
      "visual_description": "A narrow alley clogged with crates. The Sleeping Tax Collector snores on a stool, head resting on a ledger, stamped papers scattered at his feet.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox discovers a hidden mirror door.",
      "visual_description": "Tin Fox scratches at a cracked mirror set into a wall. Its reflection shows a hallway instead of the alley. Glass Diver steps forward, helmet gleaming.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Glass Diver swims through the mirror.",
      "visual_description": "Glass Diver presses a hand to the mirror surface, which ripples like water. His coat reflection scatters into shards of city light. Tin Fox watches with tilted head.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara reads the old royal banner map.",
      "visual_description": "In a small plaza, Mara lays a faded banner across a broken fountain. She traces a route with her finger while the compass needle spins. Oracle Lamp glows dimly.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march through a colonnade.",
      "visual_description": "Tall clockwork soldiers in dented armor stomp across a wide colonnade. Tin Fox hides behind a fallen pillar, blue eyes tracking their path.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver opens a sealed door from inside.",
      "visual_description": "A massive stone door with no handle. Glass Diver’s hand emerges from a mirror set in the wall, reaching for a crystal key on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The team reunites in an old plaza.",
      "visual_description": "Mara, Tin Fox, Glass Diver, and Oracle Lamp gather under a cracked arch. Torn banners flap above. The crystal key glints in Glass Diver’s hand.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector wakes and stamps a permit.",
      "visual_description": "The collector blinks awake, fumbles a stamp, and presses it onto a scrap of paper. He yawns and hands it to Mara, then curls back to sleep.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "They climb the cursed tower stairs.",
      "visual_description": "A spiral staircase with cracked steps. Oracle Lamp illuminates faded murals of old kings. Tin Fox climbs ahead, metal paws clicking on stone.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver finds the captive in a mirror room.",
      "visual_description": "A circular chamber lined with mirrors. Glass Diver stands before a reflection that holds the rescue target—a small figure bound in light. He reaches out.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The crystal key unlocks the mirror cage.",
      "visual_description": "Glass Diver inserts the crystal key into a floating lock in the mirror surface. Cracks spread across the glass, and the captive figure steps forward.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The tower begins to collapse.",
      "visual_description": "Stones fall from the ceiling. Mara grabs the rescued figure and runs. Tin Fox weaves between falling blocks. Oracle Lamp’s flame stutters.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "They reach the bridge controls.",
      "visual_description": "A stone platform with a single lever. Beyond it, a drawbridge spans a chasm. The rescued figure clings to Mara’s coat. Armored patrols approach behind them.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Glass Diver pulls the bridge lever.",
      "visual_description": "Glass Diver grips the lever with both hands. The bridge groans and lowers across the gap. Chains rattle and dust falls from the mechanism.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The rescue team crosses the bridge.",
      "visual_description": "The team hurries across wooden planks. Torn banners flutter on both sides. Below, fog hides the bottom of the chasm. The bridge creaks under their weight.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the wilderness at dawn.",
      "visual_description": "On a grassy hill beyond the bridge, the team looks back at the ruined city. Sunrise lights the towers and banners. The rescued figure stands safely with them.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

